-- ----------------------------------------------------------------------------
-- Resync id sequences after explicit ids were inserted.
-- ----------------------------------------------------------------------------
DO $$
DECLARE
    t TEXT;
    s TEXT;
    m BIGINT;
BEGIN
    FOREACH t IN ARRAY ARRAY['users', 'movies', 'theatres', 'screens',
                              'seats', 'shows', 'bookings', 'payments', 'refunds']
    LOOP
        s := pg_get_serial_sequence(t, 'id');
        EXECUTE format('SELECT COALESCE(MAX(id), 0) FROM %I', t) INTO m;
        IF s IS NOT NULL AND m > 0 THEN
            PERFORM setval(s, m);
        END IF;
    END LOOP;
END $$;
